package com.gbkhealthcare.patient;

import com.gbkhealthcare.auth.Doctor;
import com.gbkhealthcare.auth.DoctorRepository;
import org.springframework.http.HttpStatus;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.List;

@Service
public class DoctorClinicalOrderService {
    private static final ZoneId CLINIC_ZONE=ZoneId.of("Asia/Kolkata");
    private final DoctorRepository doctors; private final DoctorQueueEntryRepository queue;
    private final PrescriptionRepository prescriptions; private final InvestigationOrderRepository investigations;
    private final ReferralOrderRepository referrals; private final ClinicalOrderAuditEventRepository audit;
    public DoctorClinicalOrderService(DoctorRepository doctors,DoctorQueueEntryRepository queue,PrescriptionRepository prescriptions,InvestigationOrderRepository investigations,ReferralOrderRepository referrals,ClinicalOrderAuditEventRepository audit){this.doctors=doctors;this.queue=queue;this.prescriptions=prescriptions;this.investigations=investigations;this.referrals=referrals;this.audit=audit;}
    @Transactional(readOnly=true) public List<PrescriptionResponse> prescriptions(Jwt jwt,Long queueId){Doctor d=doctor(jwt);DoctorQueueEntry q=assigned(queueId,d.getId());return prescriptions.findAllByPatientVisit_IdOrderByRevisionDesc(q.getPatientVisit().getId()).stream().map(PrescriptionResponse::from).toList();}
    @Transactional public PrescriptionResponse createPrescription(Jwt jwt,Long queueId,PrescriptionRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());int revision=(int)prescriptions.countByPatientVisit_Id(q.getPatientVisit().getId())+1;Prescription supersedes=null;if(r.supersedesPrescriptionId()!=null){supersedes=prescriptions.findById(r.supersedesPrescriptionId()).filter(p->p.getPatientVisit().getId().equals(q.getPatientVisit().getId())&&p.getDoctor().getId().equals(d.getId())&&p.getStatus()==Prescription.State.SIGNED).orElseThrow(()->notFound("Signed prescription to replace was not found."));}LocalDateTime at=now();Prescription p=new Prescription(q.getPatientVisit(),d,revision,supersedes,r.notes(),at);p.replaceItems(r.items().stream().map(PrescriptionItem::new).toList());p=prescriptions.save(p);event(d,q,"PRESCRIPTION",p.getId(),supersedes==null?"PRESCRIPTION_DRAFT_CREATED":"PRESCRIPTION_REPLACEMENT_CREATED",at);return PrescriptionResponse.from(p);}
    @Transactional public PrescriptionResponse updatePrescription(Jwt jwt,Long queueId,Long id,PrescriptionRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());Prescription p=prescriptions.findById(id).filter(x->x.getPatientVisit().getId().equals(q.getPatientVisit().getId())&&x.getDoctor().getId().equals(d.getId())).orElseThrow(()->notFound("Prescription not found."));if(p.getStatus()!=Prescription.State.DRAFT)throw conflict("Signed prescriptions are immutable. Create a replacement version.");p.updateNotes(r.notes());p.replaceItems(r.items().stream().map(PrescriptionItem::new).toList());p=prescriptions.save(p);event(d,q,"PRESCRIPTION",p.getId(),"PRESCRIPTION_DRAFT_UPDATED",now());return PrescriptionResponse.from(p);}
    @Transactional public PrescriptionResponse signPrescription(Jwt jwt,Long queueId,Long id){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());Prescription p=prescriptions.findById(id).filter(x->x.getPatientVisit().getId().equals(q.getPatientVisit().getId())&&x.getDoctor().getId().equals(d.getId())).orElseThrow(()->notFound("Prescription not found."));LocalDateTime at=now();try{p.sign(at);}catch(IllegalStateException ex){throw conflict(ex.getMessage());}p=prescriptions.save(p);event(d,q,"PRESCRIPTION",p.getId(),"PRESCRIPTION_SIGNED",at);return PrescriptionResponse.from(p);}
    @Transactional(readOnly=true) public List<InvestigationOrderResponse> investigations(Jwt jwt,Long queueId){Doctor d=doctor(jwt);DoctorQueueEntry q=assigned(queueId,d.getId());return investigations.findAllByPatientVisit_IdOrderByOrderedAtDesc(q.getPatientVisit().getId()).stream().map(InvestigationOrderResponse::from).toList();}
    @Transactional public InvestigationOrderResponse createInvestigation(Jwt jwt,Long queueId,InvestigationOrderRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());LocalDateTime at=now();InvestigationOrder o=investigations.save(new InvestigationOrder(q.getPatientVisit(),d,r.type(),r.name(),r.indication(),r.priority(),at));event(d,q,"INVESTIGATION",o.getId(),"INVESTIGATION_ORDERED",at);return InvestigationOrderResponse.from(o);}
    @Transactional public InvestigationOrderResponse investigationStatus(Jwt jwt,Long queueId,Long id,InvestigationStatusRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());InvestigationOrder o=investigations.findById(id).filter(x->x.getPatientVisit().getId().equals(q.getPatientVisit().getId())&&x.getDoctor().getId().equals(d.getId())).orElseThrow(()->notFound("Investigation order not found."));LocalDateTime at=now();try{o.changeStatus(r.status(),at);}catch(IllegalStateException ex){throw conflict(ex.getMessage());}o=investigations.save(o);event(d,q,"INVESTIGATION",o.getId(),"INVESTIGATION_STATUS_"+o.getStatus(),at);return InvestigationOrderResponse.from(o);}
    @Transactional(readOnly=true) public List<ReferralOrderResponse> referrals(Jwt jwt,Long queueId){Doctor d=doctor(jwt);DoctorQueueEntry q=assigned(queueId,d.getId());return referrals.findAllByPatientVisit_IdOrderByCreatedAtDesc(q.getPatientVisit().getId()).stream().map(ReferralOrderResponse::from).toList();}
    @Transactional public ReferralOrderResponse createReferral(Jwt jwt,Long queueId,ReferralOrderRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());LocalDateTime at=now();ReferralOrder o=referrals.save(new ReferralOrder(q.getPatientVisit(),d,r.specialty(),r.providerOrFacility(),r.clinicalReason(),r.priority(),r.instructions(),at));event(d,q,"REFERRAL",o.getId(),"REFERRAL_CREATED",at);return ReferralOrderResponse.from(o);}
    @Transactional public ReferralOrderResponse referralStatus(Jwt jwt,Long queueId,Long id,ReferralStatusRequest r){Doctor d=doctor(jwt);DoctorQueueEntry q=editable(queueId,d.getId());ReferralOrder o=referrals.findById(id).filter(x->x.getPatientVisit().getId().equals(q.getPatientVisit().getId())&&x.getDoctor().getId().equals(d.getId())).orElseThrow(()->notFound("Referral not found."));LocalDateTime at=now();try{o.changeStatus(r.status(),at);}catch(IllegalStateException ex){throw conflict(ex.getMessage());}o=referrals.save(o);event(d,q,"REFERRAL",o.getId(),"REFERRAL_STATUS_"+o.getStatus(),at);return ReferralOrderResponse.from(o);}
    private Doctor doctor(Jwt jwt){if(jwt==null||jwt.getSubject()==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Doctor authentication is required.");Long id=null;try{Object c=jwt.getClaims().get("doctorId");if(c instanceof Number n)id=new BigDecimal(n.toString()).longValueExact();}catch(RuntimeException ignored){}if(id==null||id<1)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"A valid Doctor identity is required.");return doctors.findById(id).filter(Doctor::isEnabled).filter(d->d.getApprovalStatus()==Doctor.ApprovalStatus.APPROVED).filter(d->d.getEmail().equalsIgnoreCase(jwt.getSubject())).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Active approved Doctor account not found."));}
    private DoctorQueueEntry assigned(Long id,Long doctorId){return queue.findAssigned(id,doctorId).orElseThrow(()->notFound("Assigned Doctor encounter not found."));}
    private DoctorQueueEntry editable(Long id,Long doctorId){DoctorQueueEntry q=queue.findAssignedForUpdate(id,doctorId).orElseThrow(()->notFound("Assigned Doctor encounter not found."));if(!List.of("IN_CONSULTATION","ON_HOLD","CONSULTATION_SIGNED").contains(q.getStatus()))throw conflict("Orders are available after consultation starts.");return q;}
    private void event(Doctor d,DoctorQueueEntry q,String type,Long resource,String action,LocalDateTime at){audit.save(new ClinicalOrderAuditEvent(d.getId(),q.getPatientVisit().getId(),type,resource,action,at));}
    private static LocalDateTime now(){return LocalDateTime.now(CLINIC_ZONE);} private static ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private static ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
